export function CompanySettingsPage(){const {account,companyId,reloadMe}=useApp();const{data,error,reload}=useLoad('/auth/companies');const found=(data||[]).find(x=>x.id===companyId),[form,setForm]=useState({}),saver=useSubmit(reload);useEffect(()=>{if(found)setForm(found)},[found?.id]);
 const fields=[['name','Registered business name'],['code','Short company code'],['gstin','GSTIN'],['pan','PAN'],['phone','Phone number'],['email','Company email'],['address','Registered address'],['state','State'],['stateCode','GST state code'],['bankName','Bank name'],['bankAccount','Bank account number'],['ifsc','IFSC']];
 return <><Head title="Company configuration" description="Update legal, contact and banking details printed on estimates, POs and customer invoices."/><Notice error={error||saver.error} success={saver.success}/>{found&&<Panel title={found.name} subtitle="Each registered entity has separate tax and bank information."><div className="company-settings-logo"><img src={found.logo||'/logos/chemtex.png'} alt="Company logo"/></div><FormGrid>{fields.map(([k,label])=><TextInput key={k} label={label} value={form[k]} onChange={v=>setForm(x=>({...x,[k]:v}))}/>)}</FormGrid><div className="form-actions"><Btn disabled={account?.user?.role!=='SUPER_ADMIN'} onClick={()=>saver.submit(async()=>{const r=await request('patch',`/auth/companies/${found.id}`,form);reloadMe();return r})}>Save company settings</Btn></div><p className="subtle-note">Only super admins can edit legal company details. Verify all GSTIN, PAN, and bank details against official company records before issuing any invoice.</p></Panel>}</>;
}
export function ProfilePage(){const {account,company}=useApp();const[form,setForm]=useState({oldPassword:'',newPassword:'',confirmPassword:''}),saver=useSubmit(null,()=>setForm({oldPassword:'',newPassword:'',confirmPassword:''}));return <><Head title="Your profile & security" description="Manage your password without sharing account credentials."/><Panel title="Account details"><div className="profit-grid"><div><span>Name</span><strong>{account.user.fullName}</strong></div><div><span>Work email</span><strong>{account.user.email}</strong></div><div><span>Global account role</span><strong>{account.user.role}</strong></div><div><span>Active company</span><strong>{company.name}</strong></div></div></Panel><Panel title="Change your password" subtitle="Use at least ten characters; changing the password does not update other users."><Notice error={saver.error} success={saver.success}/><form onSubmit={e=>{e.preventDefault();if(form.newPassword!==form.confirmPassword){saver.setError('New passwords do not match');return}saver.submit(()=>request('post','/auth/change-password',form))}}><FormGrid><TextInput label="Current password" type="password" required value={form.oldPassword} onChange={v=>setForm(x=>({...x,oldPassword:v}))}/><TextInput label="New password" type="password" required value={form.newPassword} onChange={v=>setForm(x=>({...x,newPassword:v}))}/><TextInput label="Confirm new password" type="password" required value={form.confirmPassword} onChange={v=>setForm(x=>({...x,confirmPassword:v}))}/></FormGrid><div className="form-actions"><Btn type="submit">Update password</Btn></div></form></Panel></>}
